<?php
require 'db.php'; require 'functions.php'; require_admin();
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $username=trim($_POST['username']??'');$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';
 try{
  if($username===''||strlen($username)>50) throw new Exception('Enter a username with 1–50 characters.');
  $s=$pdo->prepare('SELECT password_hash FROM admins WHERE id=?');$s->execute([$_SESSION['admin_id']]);$admin=$s->fetch();
  if(!$admin||!password_verify($current,$admin['password_hash'])) throw new Exception('Your current password is incorrect.');
  if($new!=='' && (strlen($new)<10 || $new!==$confirm)) throw new Exception('New password must be at least 10 characters and both password fields must match.');
  if($new!==''){$u=$pdo->prepare('UPDATE admins SET username=?,password_hash=? WHERE id=?');$u->execute([$username,password_hash($new,PASSWORD_DEFAULT),$_SESSION['admin_id']]);}
  else{$u=$pdo->prepare('UPDATE admins SET username=? WHERE id=?');$u->execute([$username,$_SESSION['admin_id']]);}
  $_SESSION['admin_username']=$username;log_activity($pdo,'Updated admin settings','Username/password settings updated');$success='Account settings updated successfully.';
 }catch(PDOException $e){$error='That username may already be in use.';}catch(Exception $e){$error=$e->getMessage();}
}
