assword</label><input class="form-control" type="password" name="current_password" autocomplete="current-password" required></div><div class="col-md-6"><label class="form-label">New Password <small class="text-muted">(leave blank to keep current)</small></label><input class="form-control" type="password" name="new_password" minlength="10" autocomplete="new-password"></div><div class="col-md-6"><label class="form-label">Confirm New Password</label><input class="form-control" type="password" name="confirm_password" minlength="10" autocomplete="new-password"></div><div class="col-12"><button class="btn btn-primary">Save Settings</button></div></form></div></section></div></main></div></body></html>
